CREATE TABLE IF NOT EXISTS MarketSellerLegal(storeId TEXT PRIMARY KEY REFERENCES MarketStore(id),data TEXT NOT NULL,approvedData TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'PENDING',reviewNote TEXT NOT NULL DEFAULT '',updated BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS MarketSellerLegalHistory(id TEXT PRIMARY KEY,storeId TEXT NOT NULL,data TEXT NOT NULL,license TEXT NOT NULL,reviewerId TEXT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS MarketProductLegal(productId TEXT PRIMARY KEY REFERENCES MarketProduct(id),data TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'NONE',status TEXT NOT NULL DEFAULT 'APPROVED',document TEXT NOT NULL DEFAULT '',reviewNote TEXT NOT NULL DEFAULT '',reviewedBy TEXT NOT NULL DEFAULT '',reviewedAt BIGINT NOT NULL DEFAULT 0,updated BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS MarketLegalAcceptance(id TEXT PRIMARY KEY,userId TEXT NOT NULL,kind TEXT NOT NULL,version TEXT NOT NULL,snapshot TEXT NOT NULL,created BIGINT NOT NULL,UNIQUE(userId,kind,version));
CREATE TABLE IF NOT EXISTS MarketOrderDisclosure(orderId TEXT PRIMARY KEY REFERENCES MarketOrder(id),version TEXT NOT NULL,snapshot TEXT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS MarketSupportCase(id TEXT PRIMARY KEY,userId TEXT NOT NULL,orderId TEXT NOT NULL DEFAULT '',storeId TEXT NOT NULL DEFAULT '',productId TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL,subject TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',resolution TEXT NOT NULL DEFAULT '',created BIGINT NOT NULL,updated BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS MarketSupportCase_owner ON MarketSupportCase(userId,created);
CREATE INDEX IF NOT EXISTS MarketSupportCase_store ON MarketSupportCase(storeId,created);
CREATE TABLE IF NOT EXISTS MarketSupportMessage(id TEXT PRIMARY KEY,caseId TEXT NOT NULL REFERENCES MarketSupportCase(id),userId TEXT NOT NULL,role TEXT NOT NULL,body TEXT NOT NULL,evidence TEXT NOT NULL DEFAULT '',created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS MarketComplianceFile(id TEXT PRIMARY KEY,kind TEXT NOT NULL,name TEXT NOT NULL,content TEXT NOT NULL,userId TEXT NOT NULL,created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS MarketFeeSchedule(id TEXT PRIMARY KEY,storeId TEXT NOT NULL DEFAULT '',feeBps INTEGER NOT NULL CHECK(feeBps BETWEEN 0 AND 10000),starts BIGINT NOT NULL,created BIGINT NOT NULL,userId TEXT NOT NULL,cancelled INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS MarketFeeSchedule_effective ON MarketFeeSchedule(storeId,cancelled,starts);
CREATE TABLE IF NOT EXISTS MarketSellerFulfilment(orderId TEXT NOT NULL,storeId TEXT NOT NULL,state TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',updated BIGINT NOT NULL,PRIMARY KEY(orderId,storeId));
